const slider=document.getElementById('a-slider');function update(){const a=Number(slider.value),r=(1+1.5*a)/2;const put=(id,v)=>{document.getElementById(id).textContent=typeof v==='number'?v.toFixed(3):v};put('a-value',a);put('weight-left',r);put('weight-right',r);put('stretch',1+a);put('correct',2+a);put('actual',2+1.5*a);put('claimed',2+2*a);put('verdict','The actual cycle is above the corrected threshold and below the source claim.')}slider.addEventListener('input',update);document.getElementById('reset').addEventListener('click',()=>{slider.value='0.20';update()});update();